import type { components } from "./api-types.gen";

/** Response types derived from the generated API contract (single source
 * of truth: frontend/lib/api-schema.json, regenerated by `npm run gen:api`
 * and drift-gated by backend/tests/test_openapi_contract.py). Required<>
 * restores fields pydantic marks optional-with-default but always sends. */
type Schema<K extends keyof components["schemas"]> = components["schemas"][K];

/**
 * Shared domain types for Northstar.
 *
 * These intentionally mirror the Northstar Supabase schema (Day 2 migration)
 * rather than the interim Northstar V1 schema, so the UI is already typed
 * against the shape the backend will serve. No runtime data exists for any of
 * these types yet; they are compile-time contracts only.
 */

export type OpportunityField =
  | "cs"
  | "biology"
  | "math"
  | "physics"
  | "engineering"
  | "interdisciplinary";

export type OpportunityType =
  | "program"
  | "scholarship"
  | "competition"
  | "mentorship";

export type DemographicEligibility = "first_gen" | "urm" | "women_only" | "any";

export type Opportunity = {
  id: string;
  title: string;
  host: string;
  field: OpportunityField;
  type: OpportunityType;
  /** Short marketing blurb used on cards. */
  blurb: string;
  /** Long description shown on the detail page. */
  description: string;
  /** ISO date string or null when the deadline is rolling. */
  deadline: string | null;
  /** Program cost in USD; 0 means fully funded. */
  cost: number;
  grade_min: number;
  grade_max: number;
  url: string;
  tags: string[];
  /** Optional geographic location for map placement. */
  location: string | null;
};

export type MatchScore = {
  opportunity_id: string;
  /** TF-IDF cosine similarity in [0, 1]. */
  score: number;
  /** One-line, human-readable explanation for the judge-facing demo. */
  explanation: string;
};

export type MatchResult = {
  opportunity: Opportunity;
  score: MatchScore;
};

export type Bookmark = {
  id: string;
  opportunity_id: string;
  created_at: string;
};

export type OutcomeStatus =
  | "accepted"
  | "rejected"
  | "waitlisted"
  | "withdrew"
  | "completed";

/** A student-reported result, mirroring backend/app/schemas.py Outcome. */
export type Outcome = {
  id: string;
  opportunity_id: string;
  status: OutcomeStatus;
  impact_notes: string | null;
  created_at: string | null;
};

export type Audience = "high_school" | "college";

export type StudentProfile = Required<Schema<"StudentProfile">>;

/** A GitHub repository recommendation from GET /projects. */
export type ProjectRec = {
  field: OpportunityField;
  score: number;
  explanation: string;
  repo: {
    full_name: string;
    html_url: string;
    description: string;
    stars: number;
    language: string;
    topics: string[];
    good_first_issues_url: string;
  };
};

/** A proof mission from GET /missions. */
export type Mission = Required<Schema<"Mission">>;

/** The student's completion record for a mission. */
export type MissionCompletion = Required<Schema<"MissionCompletion">>;

/** One event in the evidence timeline (GET /timeline). */
export type TimelineEvent = {
  kind: "assessment" | "mission" | "outcome" | "bookmark" | "dismissal";
  at: string | null;
  title: string;
  detail: string;
};
